"""Build self-contained three-scenario replay and relative evidence/code assets."""
from pathlib import Path
import json,zipfile,shutil,html
R=Path(__file__).resolve().parents[1]
scenarios={k:json.loads((R/'static'/f'scenario-v5-{k}.json').read_text()) for k in ['A','B','C']};evaluation=json.loads((R/'evaluation/v5/final/summary.json').read_text())
s=(R/'static/index.html').read_text().replace('const REPLAY = false','const REPLAY = true');inject='window.PREPARED_SCENARIOS='+json.dumps(scenarios).replace('<','\\u003c')+';\nwindow.PREPARED_EVALUATION='+json.dumps(evaluation).replace('<','\\u003c')+';\n';s=s.replace('<script>','<script>\n'+inject,1);(R/'demo/index.html').write_text(s)
# Source snapshot: no runtime/model binaries, identity or researcher responses.
code=R/'demo/downloads/benchsloth-source.zip';code.parent.mkdir(parents=True,exist_ok=True)
with zipfile.ZipFile(code,'w',zipfile.ZIP_DEFLATED) as z:
 for f in [*R.glob('*.py'),*R.glob('requirements*.txt'),R/'LICENSE',R/'eval/sample_prepared.json',R/'static/index.html',*(R/'static').glob('scenario-v5-*.json')]:z.write(f,'benchsloth/'+str(f.relative_to(R)))
with zipfile.ZipFile(code,'a',zipfile.ZIP_DEFLATED) as z:z.writestr('benchsloth/README.md','# BenchSloth core source snapshot\n\nThis ZIP is for inspecting the application code. It excludes large media, historical evidence and its own downloadable ZIP. The complete reviewed release and public repository contain those assets. Actual inference requires Python, requirements-dev.txt, Ollama and separately downloaded Gemma3:4b weights. Run uvicorn server_v5:app --host 127.0.0.1 --port 8771 after installing dependencies. Source-only helper and media routes require the full release package. No model/runtime binaries, Git metadata or reviewer responses are included. Original source uses MIT; Gemma weights have separate Google terms.\n')
e=R/'demo/evidence';e.mkdir(exist_ok=True);(e/'summary.json').write_text(json.dumps(evaluation,indent=2)+'\n');boundary=json.loads((R/'evaluation/v5/boundary-run/summary.json').read_text());(e/'boundary-summary.json').write_text(json.dumps(boundary,indent=2)+'\n')
rows=''
for method in ['rules','v4','v5']:
 for group,m in evaluation[method]['groups'].items():rows+=f'<tr><td>{method}</td><td>{group} lines</td><td>{m["tp"]}/{m["gold_links"]}</td><td>{m["fp"]}</td><td>{m["fn"]}</td><td>{m["correct_waits"]}/{m["gold_waits"]}</td><td>{m["unsupported_timer_decisions"]}</td><td>{m["complete_workflows"]}/{m["cases"]}</td><td>{m["mean_seconds"]:.2f}s</td></tr>'
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>BenchSloth · evidence and limits</title><style>body{font:16px/1.7 system-ui;background:#f8f6f0;color:#17352e;max-width:1100px;margin:auto;padding:28px}h1,h2{font-family:Georgia}td,th{text-align:left;padding:12px;border-bottom:1px solid #cbd2c7}a{color:inherit}.table{overflow:auto}</style><h1>Evidence before a score.</h1><p>Twenty frozen synthetic cases spanning 1–15 source lines, reported in length bins through 13–25; three separate boundary checks reach 25 lines. Assistant-authored, implementer-visible labels; independent adjudication pending. Original failures and all prior benchmarks remain unchanged. Exact plans match the complete reference link and timer-ID sets; they do not measure human or physical completion. No measured human time savings. A zero on this sample is not proof of general safety.</p><div class="table"><table><thead><tr><th>Approach</th><th>Length</th><th>Exact links</th><th>Wrong</th><th>Missed</th><th>Eligible waits</th><th>Unsupported waits</th><th>Exact plans</th><th>Mean latency</th></tr></thead><tbody>ROWS</tbody></table></div><h2>Interpretation and limits</h2><p>The strongest rules baseline shares section/candidate logic and source restrictions with v5. V4 is the unchanged whole-protocol pipeline. V5 uses focused Gemma classification only for uniquely supported candidate targets; structural abstention makes no model call. Compare every length group, not just the aggregate. Any corrected display is identified as human input, never retroactively counted as model accuracy. Ambiguous references remain for review. Long paragraphs remain one occurrence; the system does not claim sentence-level comprehension.</p><p>Separate boundary supplement: three actual 18/21/25-line cases, frozen after engine selection but before inference. V5 and strong rules:6/6 links,3/3 waits,0 unsupported; unchanged v4:1/6 links,2/3 waits,0 unsupported. This is not pooled into the preselection 20-case set. <a href="boundary-summary.json">Boundary metrics JSON</a>. Completed human participants: 0. The recruited-researcher packet is ready; no responses are included. Current static content is a prepared replay, not browser-based Gemma. Scenario C comes from an actual recorded 13-line run and exposes its real outputs.</p><p><a href="summary.json">Download full machine-readable metrics</a> · <a href="../downloads/benchsloth-source.zip">Inspect core source ZIP</a> · <a href="../index.html">Return to demo</a></p></html>'''.replace('ROWS',rows);(e/'index.html').write_text(page)
for name in [f.name for f in (R/'assets/v5').glob('*') if f.suffix in ['.webm','.png','.svg']]:
 source=R/'assets/v5'/name
 if source.exists():target=R/'demo/assets/v5'/name;target.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(source,target)
print('Built3scenarios, HTML bytes',len(s.encode()),'source snapshot',code.stat().st_size)
